def brute(edges,start,end,hops):
    options=[]
    def visit(node,path,costs):
        if node==end:
            cost=sum(costs)-max([c-c//2 for c in costs]+[0]); options.append((cost,len(costs),tuple(path)))
        if len(costs)<hops:
            for a,b,c in edges:
                if a==node: visit(b,path+[b],costs+[c])
    visit(start,[start],[])
    if not options: return None
    cost,_,path=min(options); return cost,path
def test_hidden():
    r=random.Random(9721)
    for _ in range(60):
        e=[(r.choice('abc'),r.choice('abc'),r.randrange(9)) for _ in range(6)]; before=e[:]
        assert coupon_route(e,'a','c',4)==brute(e,'a','c',4); assert e==before
    assert coupon_route([('a','c',4),('a','b',0),('b','c',4)],'a','c',2)==(2,('a','c'))
    assert coupon_route([], 'a','a',0)==(0,('a',))
    for e,h in [([('x','y',True)],0),([('x','y',-1)],0),([],False)]:
        with pytest.raises(ValueError): coupon_route(e,'a','a',h)


def test_checkpoint_discounts():
    assert coupon_route([('a','b',8),('b','c',8),('c','d',8)],'a','d',3,(),3)==(16,('a','b','c','d'))
    assert coupon_route([('a','a',0)],'a','a',2,('a','a'))==(0,('a','a'))
    assert coupon_route([('a','b',2),('b','a',2)],'a','a',2,('b',))==(3,('a','b','a'))
    assert coupon_route([], 'a','a',0,('a','a')) is None
    for req,n in [(('a',),True),((False,),1),(['a'],1)]:
        with pytest.raises(ValueError): coupon_route([], 'a','a',0,req,n)
